import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  const colors = config.intent?.visualSpec?.colors ?? {};
  const accentHex = colors.accent ?? '#ff2a38';
  const paperHex = colors.paper ?? '#e8ecf2';

  const W = 1.5, H = 0.5;

  // ---- backdrop panel (vertical gradient surface->ink-ish, never flat void) ----
  const panelMat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  panelMat.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.082, 0.082, 0.113),
    smoothstep(0.0, 1.0, uv().y)
  );
  const panelGeo = new THREE.PlaneGeometry(W, H);
  const panel = new THREE.Mesh(panelGeo, panelMat);
  group.add(panel);

  // ---- accent left edge strip ----
  const stripMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(accentHex),
    side: THREE.DoubleSide
  });
  const stripGeo = new THREE.PlaneGeometry(0.04, H * 0.92);
  const strip = new THREE.Mesh(stripGeo, stripMat);
  strip.position.set(-W / 2 + 0.04, 0, 0.001);
  group.add(strip);

  // ---- floating accent image decor (right side) ----
  let accentImgMesh = null;
  let imgMat = null;
  let imgGeo = null;
  if (config.imageUrl) {
    imgMat = new MeshBasicNodeMaterial({ transparent: true, side: THREE.DoubleSide });
    imgGeo = new THREE.PlaneGeometry(0.22, 0.22);
    accentImgMesh = new THREE.Mesh(imgGeo, imgMat);
    accentImgMesh.position.set(W / 2 - 0.22, 0, 0.002);
    group.add(accentImgMesh);
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // ---- MSDF text headline ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const txtItem = items.find((it) => it.role === 'headline') ?? items[0];
  if (txtItem) {
    const txt = ctx.fontAtlas.createText(String(txtItem.text), {
      fontSize: 39,
      color: new THREE.Color(paperHex),
      align: 'left',
      letterSpacingPx: 1
    });
    txt.position.set(-W / 2 + 0.14, 0, 0.002);
    group.add(txt);
  }

  // ---- interaction handlers ----
  const timelines = [];
  group.userData.handlers = {
    pointerenter: () => {
      const t = gsap.timeline();
      t.to(group.position, { y: '+=0.15', duration: 0.55, ease: 'power3.out' });
      t.to(strip.scale, { y: 1.1, duration: 0.4, ease: 'power2.out' }, '<');
      t.to(strip.material, {
        aMod: 0,
        duration: 0.001,
        onComplete: () => {}
      });
      timelines.push(t);
    },
    pointerleave: () => {
      const t = gsap.timeline();
      t.to(group.position, { y: '-=0.15', duration: 0.45, ease: 'power3.out' });
      t.to(strip.scale, { y: 1.0, duration: 0.35, ease: 'power2.inOut' }, '<');
      timelines.push(t);
    },
    click: () => {
      const t = gsap.timeline();
      t.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.in(2)' });
      t.to(group.scale, { x: 1.0, y: 1.0, duration: 0.5, ease: 'back.out(2)' });
      ctx.emit('hub-journal.select', { id: 'journal-3', label: txtItem?.text ?? 'Journal 3' });
      ctx.emit('navigate', { to: 'hub-journal' });
      timelines.push(t);
    }
  };

  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    timelines.length = 0;
    panelGeo.dispose();
    panelMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    if (imgGeo) imgGeo.dispose();
    if (imgMat) imgMat.dispose();
  };

  return group;
}
